export function twinCutoverPins(input: {
  champion: ConversationTextChampion;
  registryVersion: number;
  /** The t_auto the loaded fast-path policy actually enforced this run. */
  tAuto: number;
}): Record<string, unknown> {
  // The single source of the pin list: the constants the production assembly
  // itself resolves, so the manifest cannot drift from what actually ran
  // (SPEC #107 "Versioning, cutover, rollback").
  return {
    conversationActionCatalog: {
      actionKinds:
        MEMORY_TRUST_ACTIONS_CONVERSATION_ACTION_CATALOG.definitions.map(
          (definition) => definition.actionKind,
        ),
      version: MEMORY_TRUST_ACTIONS_CONVERSATION_ACTION_CATALOG.version,
    },
    entityResolvePolicy: {
      policyVersion: ENTITY_RESOLVE_GATE_POLICY_VERSION,
      tAuto: input.tAuto,
    },
    fastPathExtractionPolicyVersion: FAST_PATH_EXTRACTION_POLICY_VERSION,
    harnessPolicyVersion: CATALOG_V2_CONVERSATION_HARNESS_POLICY.version,
    localePacks: {
      chinese: CHINESE_LOCALE_PACK_VERSION,
      english: ENGLISH_LOCALE_PACK_VERSION,
    },
    memoryConsolidationPolicyVersion: MEMORY_CONSOLIDATION_POLICY_VERSION,
    memoryRetrieval: {
      memoryBudgets: MEMORY_BUDGETS_POLICY_VERSION,
      policyVersion: MEMORY_RETRIEVAL_POLICY_VERSION,
      portraitSelection: PORTRAIT_SELECTION_POLICY_VERSION,
      queryConstruction: RETRIEVAL_QUERY_CONSTRUCTION_POLICY_VERSION,
    },
    persona: {
      anchors: PERSONA_BEHAVIOR_ANCHORS_VERSION,
      canonical: CANONICAL_PERSONA_VERSION,
      invariant: PERSONA_CONTRACT_INVARIANT_VERSION,
    },
    predicateRegistry: {
      registryVersion: input.registryVersion,
      version: "predicate-registry:v1",
    },
    promptArtifacts: {
      groundingGuardAndOpenerPermission: RECALL_EXPERIENCE_CONTRACT_VERSION,
      trustActionExpression: TRUST_ACTION_EXPRESSION_CONTRACT_VERSION,
    },
    safetyResources: SAFETY_RESOURCE_WHITELIST_VERSION,
    taskInstructionVersion: CONVERSATION_DECISION_TASK_INSTRUCTION_VERSION,
  };
}

async function readNdjson(
  response: Response,
): Promise<readonly Record<string, unknown>[]> {
  const text = await response.text();
  return text
    .split("\n")
    .filter((line) => line.length > 0)
    .map((line) => JSON.parse(line) as Record<string, unknown>);
}

function joinDeltas(events: readonly Record<string, unknown>[]): string {
  return events
    .filter((event) => event.type === "assistant_delta")
    .map((event) => String(event.delta ?? ""))
    .join("");
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function summarizeReceipt(
  receipt: Record<string, unknown>,
): Record<string, unknown> {
  const summary: Record<string, unknown> = {};
  for (const key of [
    "actionKind",
    "admission",
    "catalogVersion",
    "disposition",
    "execution",
    "finalization",
    "receiptSequence",
  ]) {
    if (receipt[key] !== undefined) {
      summary[key] = receipt[key];
    }
  }
  return summary;
}

type CompiledContextRow = Readonly<{
  compiled_context_id: string;
  retrieval_manifest: unknown;
}>;

/**
 * Read the turn's just-committed CompiledContext for memory evidence: the
 * injected items come from the retrieval run's candidate rows (selected
 * section + reason codes), and the run summary from the compiled manifest.
 */
async function loadTurnMemoryEvidence(
  pool: Pool,
  userId: string,
): Promise<{
  injectedMemories: TwinCapturedTurn["injectedMemories"];
  retrieval: TwinCapturedTurn["retrieval"];
}> {
  const result = await pool.query<CompiledContextRow>(
    `SELECT compiled_context_id::text AS compiled_context_id, retrieval_manifest
     FROM compiled_contexts
     WHERE user_id = $1
     ORDER BY created_at DESC, compiled_context_id DESC
     LIMIT 1`,
    [userId],
  );
  const row = result.rows[0];
  if (!row) {
    return {
      injectedMemories: [],
      retrieval: {
        runId: null,
        status: null,
        degradedReasonCodes: [],
        durationMs: null,
        deadlineMs: null,
        selectionPolicyVersions: null,
      },
    };
  }
  const injected = await pool.query<{
    selected_section: string;
    memory_claim_version_id: string;
    selection_reason_codes: string[];
  }>(
    `SELECT candidates.selected_section, candidates.memory_claim_version_id::text,
            candidates.selection_reason_codes
     FROM retrieval_run_candidates candidates
     INNER JOIN retrieval_runs runs
       ON runs.retrieval_run_id = candidates.retrieval_run_id
     WHERE runs.compiled_context_id = $1
       AND candidates.selected_section IS NOT NULL`,
    [row.compiled_context_id],
  );
  const injectedMemories = injected.rows.map((candidate) => ({
    claimVersionId: candidate.memory_claim_version_id,
    kind: candidate.selected_section === "ai_impression"
      ? "ai_impression"
      : candidate.selected_section === "person_portrait"
        ? "person_portrait"
        : "objective_memory",
    section: candidate.selected_section,
    selectionSource: candidate.selection_reason_codes.join(","),
  }));
  const manifest = isRecord(row.retrieval_manifest)
    ? row.retrieval_manifest
    : null;
  return {
    injectedMemories,
    retrieval: {
      runId: manifest ? String(manifest.retrieval_run_id ?? "") || null : null,
      status: manifest ? "recorded" : null,
      degradedReasonCodes:
        manifest && Array.isArray(manifest.degraded_reason_codes)
          ? manifest.degraded_reason_codes.map(String)
          : [],
      durationMs:
        manifest && typeof manifest.duration_ms === "number"
          ? manifest.duration_ms
          : null,
      deadlineMs:
        manifest && typeof manifest.deadline_ms === "number"
          ? manifest.deadline_ms
          : null,
      selectionPolicyVersions:
        manifest && isRecord(manifest.selection_policy_versions)
          ? Object.fromEntries(
              Object.entries(manifest.selection_policy_versions).map(
                ([key, value]) => [key, String(value)],
              ),
            )
          : null,
    },
  };
}

export async function runTwinCapture(input: {
  arm: TwinArm;
  champion: ConversationTextChampion;
  conversationAdapter: TwinConversationAdapter;
  domainClockStartIso?: string;
  log?: (line: string) => void;
  pool: Pool;
  roleRegistry: TwinRoleRegistry;
  scenarioFile: Readonly<{
    path: string;
    scenarioCount: number;
    onlyFilter?: readonly string[];
    sha256?: string;
  }>;
  scenarios: readonly TwinScenario[];
}): Promise<{ manifest: TwinManifest; transcripts: TwinTranscriptsFile }> {
  const {
    arm,
    champion,
    conversationAdapter,
    log = () => {},
    pool,
    roleRegistry,
    scenarioFile,
    scenarios,
  } = input;
  if (scenarios.length === 0) {
    throw new Error("Twin capture requires a non-empty scenario list.");
  }
  const memoryOn = arm === "on";
  const runStartedAt = new Date();
  const domainClockStart =
    input.domainClockStartIso ?? DOMAIN_CLOCK_START_ISO;

  // ── provisioning (idempotent; mirrors the baseline capture script) ────────
  const ownerAccess = new PostgresInternalOwnerAccessRepository(pool);
  await ownerAccess.provisionInternalOwner({
    issuer: "https://github.com",
    subject: "memory-twin-owner",
    userId: fixedInternalOwnerPrincipal.userId,
  });
  await pool.query("UPDATE app_users SET status = 'active', data_epoch = 1");
  await pool.query(
    "UPDATE provider_egress_policy_versions SET status = 'active'",
  );
  // Idempotent across repeated harness runs on one schema (the system test):
  // the synthetic backup evidence row is recorded once and reused.
  const existingBackupEvidence = await pool.query(
    `SELECT 1 FROM backup_policy_versions WHERE policy_version = $1 LIMIT 1`,
    [SYNTHETIC_BACKUP_POLICY_VERSION],
  );
  if (existingBackupEvidence.rowCount === 0) {
    await ownerAccess.recordBackupPolicyEvidence({
      backupPolicyId: "01984477-31e1-7595-92c6-06889cb0fdde",
      configurationFingerprint: SYNTHETIC_BACKUP_FINGERPRINT,
      databaseRetentionDays: 30,
      evidenceReference: `memory twin capture arm=${arm} (issue #126)`,
      policyVersion: SYNTHETIC_BACKUP_POLICY_VERSION,
      pitrRetentionDays: 7,
      snapshotRetentionDays: 30,
      status: "verified",
      validUntil: new Date("2026-09-21T00:00:00.000Z"),
      verifiedAt: new Date("2026-08-20T00:00:00.000Z"),
    });
  }

  // ── the memory production assembly (mirrors server-composition.ts) ───────
  const clockStart = new Date(domainClockStart);
  let domainNow = clockStart;
  const clock = () => domainNow;

  const predicateRegistrySnapshot = loadPredicateRegistrySnapshot(1);
  const predicateRegistryLookup = {
    entryFor(predicateId: string) {
      return (
        predicateRegistrySnapshot.entries.find(
          (entry) => entry.predicateId === predicateId,
        ) ?? null
      );
    },
    registryVersion: () => predicateRegistrySnapshot.registryVersion,
    relationshipProjectionsFor(predicateId: string) {
      return predicateRegistrySnapshot.relationshipProjections.filter(
        (projection) => projection.predicateId === predicateId,
      );
    },
    predicateLocalizationsFor(predicateId: string) {
      return predicateRegistrySnapshot.localizations.filter(
        (localization) => localization.predicateId === predicateId,
      );
    },
  };

  const entityRepository = new PostgresEntityRepository(pool);
  const entityService = createEntityService({
    repository: entityRepository,
    clock,
  });
  const fastPathExtractionRepository =
    new PostgresFastPathExtractionRepository(pool);
  const fastPathPolicyPromise = fastPathExtractionRepository.loadPolicy(
    FAST_PATH_EXTRACTION_POLICY_VERSION,
  );
  const memoryExtractConfiguration = roleRegistry.configuration("memory.extract");
  const entityResolveConfiguration = roleRegistry.configuration("entity.resolve");
  const memoryConsolidateConfiguration =
    roleRegistry.configuration("memory.consolidate");

  const fastPathExtractionEntrypointDependencies = async (
    workflowReceiptId: string,
  ): Promise<FastPathExtractionEntrypointDependencies> => {
    const policy = await fastPathPolicyPromise;
    if (!policy) {
      throw new Error(
        "Fast path extraction policy is unavailable or has drifted.",
      );
    }
    return {
      clock,
      repository: fastPathExtractionRepository,
      entityService,
      entityRepository,
      memoryExtract: roleRegistry.memoryExtractor as never,
      entityResolve: roleRegistry.entityResolver as never,
      registry: {
        entryFor: predicateRegistryLookup.entryFor,
        registryVersion: predicateRegistryLookup.registryVersion,
      },
      policy: {
        version: policy.version,
        visibilityTargetMs: policy.visibilityTargetMs,
        maxBatchRevisions: policy.maxBatchRevisions,
        tAuto: policy.tAuto,
        maxCandidates: policy.maxCandidates,
      },
      memoryExtractConfiguration: {
        role: "memory.extract",
        configVersion: memoryExtractConfiguration.configVersion,
        modelVersion: memoryExtractConfiguration.model,
        promptVersion: memoryExtractConfiguration.promptFingerprint,
        fallback: { mode: "disabled" },
      },
      entityResolveConfiguration: {
        role: "entity.resolve",
        configVersion: entityResolveConfiguration.configVersion,
        modelVersion: entityResolveConfiguration.model,
        promptVersion: entityResolveConfiguration.promptFingerprint,
        fallback: { mode: "disabled" },
      },
      evidenceChampion: {
        provider:
          memoryExtractConfiguration.provider === "deterministic"
            ? champion.provider
            : memoryExtractConfiguration.provider,
        model: memoryExtractConfiguration.model,
        configVersion: memoryExtractConfiguration.configVersion,
        snapshot: memoryExtractConfiguration.promptFingerprint,
        providerPolicyVersion: champion.providerPolicyVersion,
      },
      dedupeFingerprintSecret: SYNTHETIC_CONTEXT_HMAC_SECRET,
      workflowReceiptId,
    } as FastPathExtractionEntrypointDependencies;
  };

  const memoryConsolidationRepository =
    new PostgresMemoryConsolidationRepository(pool);
  const memoryConsolidationScan = createMemoryConsolidationScanService({
    clock,
    policyVersion: MEMORY_CONSOLIDATION_POLICY_VERSION,
    repository: memoryConsolidationRepository,
    enabled: memoryOn,
  });
  const memoryConsolidationEntrypointDependencies = async (
    workflowReceiptId: string,
  ): Promise<MemoryConsolidationEntrypointDependencies> =>
    ({
      clock,
      repository: memoryConsolidationRepository,
      memoryConsolidate: roleRegistry.memoryConsolidator as never,
      memoryConsolidateConfiguration: {
        role: "memory.consolidate",
        configVersion: memoryConsolidateConfiguration.configVersion,
        modelVersion: memoryConsolidateConfiguration.model,
        promptVersion: memoryConsolidateConfiguration.promptFingerprint,
        fallback: { mode: "disabled" },
      },
      registry: predicateRegistryLookup,
      policy: { version: MEMORY_CONSOLIDATION_POLICY_VERSION },
      dedupeFingerprintSecret: SYNTHETIC_CONTEXT_HMAC_SECRET,
      workflowReceiptId,
    }) as MemoryConsolidationEntrypointDependencies;

  const outboxDispatcherRepository = new PostgresOutboxDispatcherRepository(
    pool,
  );
  let workflowCounter = 0;
  let dispatchFailureLog: readonly Readonly<{
    event: string;
    reason: string;
  }>[] = [];
  const dispatch = async (): Promise<{ dispatched: number; failed: number }> => {
    const dispatcher = createOutboxDispatcherService({
      clock,
      leaseDurationMs: 60_000,
      leaseOwner: `memory-twin-${arm}`,
      repository: outboxDispatcherRepository,
      // Production runs these entrypoints as durable workflows, which retry
      // transient provider failures; a single-shot dispatch would understate
      // production. Bounded retry with backoff keeps the harness faithful.
      startWorkflow: async (event: {
        eventType: string;
        policyVersion: string;
        workflowCommandId: string;
      }) => {
        workflowCounter += 1;
        const receipt = `wf-twin-${arm}-${workflowCounter}`;
        const runOnce = async (): Promise<void> => {
          if (event.eventType === "fast_path_extraction_requested") {
            const result = await runFastPathExtraction({
              command: {
                workflowCommandId: event.workflowCommandId,
                policyVersion: event.policyVersion,
              },
              dependencies: await fastPathExtractionEntrypointDependencies(
                receipt,
              ),
            });
            // Provider failures converge inside the entrypoint as
            // retryable_failed (a run row, not a throw). Rethrow so the
            // bounded dispatch retry below fires — production durable
            // workflows retry these; a swallowed outcome would permanently
            // drop the revision's extraction (issue #126 evidence runs).
            if (result.outcome === "retryable_failed") {
              throw new Error("fast path extraction ended retryable_failed");
            }
          } else if (
            event.eventType === "daily_consolidation_requested" ||
            event.eventType === "weekly_consolidation_requested" ||
            event.eventType === "memory_sweeper_requested"
          ) {
            const result = await runMemoryConsolidation({
              command: {
                workflowCommandId: event.workflowCommandId,
                policyVersion: event.policyVersion,
              },
              dependencies: await memoryConsolidationEntrypointDependencies(
                receipt,
              ),
            });
            // Same swallow shape as fast path: retryable provider failures
            // must surface to the dispatch retry, not converge silently.
            if (result.outcome === "retryable_failed") {
              throw new Error("memory consolidation ended retryable_failed");
            }
          } else if (
            event.eventType === "memory_correction_followup_requested" ||
            event.eventType === "entity_identity_revalidation_requested" ||
            event.eventType === "journal_eligibility_requested" ||
            event.eventType === "rolling_summary_requested" ||
            event.eventType === "dialogue_state_requested"
          ) {
            // Out of scope for the twin comparison (the incumbent baseline
            // runs never started those projectors either); the command is
            // marked dispatched so the outbox stays observable and clean.
          } else {
            throw new Error(
              `Unsupported outbox event type: ${event.eventType}`,
            );
          }
        };
        const attempts = 3;
        for (let attempt = 1; ; attempt += 1) {
          try {
            await runOnce();
            return { workflowReceiptId: receipt };
          } catch (error) {
            if (attempt >= attempts) {
              dispatchFailureLog = [
                ...dispatchFailureLog,
                {
                  event: event.eventType,
                  reason: error instanceof Error
                    ? error.message.slice(0, 200)
                    : String(error).slice(0, 200),
                },
              ];
              throw error;
            }
            // Idempotent entrypoints converge on replay; the backoff mirrors
            // platform workflow retry pacing.
            await new Promise((resolve) => setTimeout(resolve, 5_000));
          }
        }
      },
    });
    return dispatcher.dispatchPending();
  };

  const generationPolicy: GenerationPolicy = {
    consentPolicyVersion: champion.consentPolicyVersion,
    freshnessPolicy: "source_valid:v1" as const,
    chineseLocalePackVersion: CHINESE_LOCALE_PACK_VERSION,
    englishLocalePackVersion: ENGLISH_LOCALE_PACK_VERSION,
    harnessPolicyVersion: CATALOG_V2_CONVERSATION_HARNESS_POLICY.version,
    conversationActionCatalogVersion:
      MEMORY_TRUST_ACTIONS_CONVERSATION_ACTION_CATALOG.version,
    model: champion.model,
    modelConfigVersion: champion.configVersion,
    modelSnapshot: champion.snapshot,
    outputFormatVersion: "conversation-output:v1",
    canonicalPersonaVersion: CANONICAL_PERSONA_VERSION,
    personaBehaviorAnchorsVersion: PERSONA_BEHAVIOR_ANCHORS_VERSION,
    personaContractInvariantVersion: PERSONA_CONTRACT_INVARIANT_VERSION,
    productPolicyVersion: "product-policy:v1",
    taskInstructionVersion: CONVERSATION_DECISION_TASK_INSTRUCTION_VERSION,
    provider: champion.provider,
    providerPolicyVersion: champion.providerPolicyVersion,
    relationshipPolicyVersion: "relationship-boundary:v1",
    safetyPolicyVersion: "minimum-high-risk-response:v1",
  };
  const inactivityPolicy = {
    timeoutMs: 30 * 60 * 1_000,
    version: "continuous-exchange-inactivity:v1",
  } as const;

  const conversationService = createUserTextConversationService({
    clock,
    expectedBackupPolicyVersion: SYNTHETIC_BACKUP_POLICY_VERSION,
    expectedConfigurationFingerprint: SYNTHETIC_BACKUP_FINGERPRINT,
    fastPathExtractionPolicyVersion: memoryOn
      ? FAST_PATH_EXTRACTION_POLICY_VERSION
      : null,
    generationPolicy,
    inactivityPolicy,
    repository: new PostgresUserTextConversationRepository(pool),
  });
  const responseRepository = new PostgresConversationResponseRepository(pool);

  const memoryRetrievalPort = memoryOn
    ? createMemoryRetrievalService({
        repository: new PostgresMemoryRetrievalRepository(pool),
        registry: {
          registryVersion: predicateRegistrySnapshot.registryVersion,
          entryFor: predicateRegistryLookup.entryFor,
          localizations: predicateRegistrySnapshot.localizations,
        },
        clock,
      })
    : undefined;
  const contextCompiler = createContextCompiler({
    clock,
    compilerVersion: "context-compiler:v1",
    contentHmacSecret: SYNTHETIC_CONTEXT_HMAC_SECRET,
    rawEventTokenBudget: 4_000,
    repository: responseRepository,
    ...(memoryRetrievalPort ? { memoryRetrieval: memoryRetrievalPort } : {}),
  });
  const egressPort = createRuntimeProviderEgressPort({
    adapter: toProviderAdapterConfig(conversationAdapter),
    champion,
    clock,
    contextCompiler,
    repository: responseRepository,
  });

  // #119: trust-action commit port + admission-time target resolver (ADR-0118).
  const memoryTrustActionProjectionProvider = {
    relationshipHintsFor(predicateId: string) {
      const entry = predicateRegistryLookup.entryFor(predicateId);
      return entry
        ? relationshipHintInputsFor(predicateRegistryLookup, entry)
        : null;
    },
    retrievalProjectionFor(predicateId: string) {
      const entry = predicateRegistryLookup.entryFor(predicateId);
      return entry
        ? retrievalProjectionInputsFor(predicateRegistryLookup, entry)
        : null;
    },
  };
  const memoryTrustActionCommitPort = new PostgresMemoryTrustActionCommitPort(
    memoryTrustActionProjectionProvider,
  );
  const memoryTrustActionTargetSource = new PostgresMemoryTrustActionTargetSource(
    pool,
  );
  const trustActionPredicateSurfaces = new Map(
    predicateRegistrySnapshot.localizations
      .flatMap((localization) =>
        localization.lexicalSurfaces.map((surface) => ({
          predicateId: localization.predicateId,
          surface: normalizeRetrievalTerm(surface.text),
        })),
      )
      .reduce((byPredicate, entry) => {
        const existing = byPredicate.get(entry.predicateId) ?? [];
        byPredicate.set(entry.predicateId, [...existing, entry.surface]);
        return byPredicate;
      }, new Map<string, readonly string[]>()),
  );
  const trustActionTargetResolver: TrustActionTargetResolver = {
    async resolve({ actionKind, anchor, userId }) {
      if (
        actionKind !== "memory_correction" &&
        actionKind !== "explain_memory_source" &&
        actionKind !== "memory_forget_request" &&
        actionKind !== "memory_forget_reversal"
      ) {
        throw new Error(
          `No trust-action search space is defined for kind "${actionKind}".`,
        );
      }
      const [candidates, labelIndex] = await Promise.all([
        memoryTrustActionTargetSource.listResolutionCandidates({
          limit: 100,
          searchSpace:
            actionKind === "memory_correction"
              ? "active_and_corrected"
              : actionKind === "explain_memory_source"
                ? "active_claims"
                : actionKind === "memory_forget_reversal"
                  ? "fenced_targets"
                  : "forget_targets",
          userId,
        }),
        memoryTrustActionTargetSource.listLabelIndex({ userId }),
      ]);
      const plan = planTrustActionTargetResolution({
        anchor,
        broadTerms: RETRIEVAL_BROAD_TERM_STOP_LIST,
        candidates: candidates.map((candidate) => ({
          ...candidate,
          predicateSurfaces:
            trustActionPredicateSurfaces.get(candidate.predicateId) ?? [],
        })),
        labelIndex,
      });
      if (plan.outcome === "unique") {
        return { outcome: "unique", target: plan.target };
      }
      if (plan.outcome === "multi_hit") {
        return { candidateCount: plan.candidateCount, outcome: "multi_hit" };
      }
      if (plan.outcome === "scope_ambiguous") {
        return { outcome: "scope_ambiguous" };
      }
      return { outcome: "zero_hit" };
    },
  };
  const actionGateway = createConversationActionGateway({
    handlers: [
      createJournalRegenerationActionHandler({
        generationPolicyVersion: "journal-generation:v2",
      }),
      createMemoryCorrectionActionHandler({
        commitPort: memoryTrustActionCommitPort,
      }),
      createExplainMemorySourceActionHandler({
        commitPort: memoryTrustActionCommitPort,
      }),
      createMemoryForgetRequestActionHandler({
        commitPort: memoryTrustActionCommitPort,
      }),
      createMemoryForgetReversalActionHandler({
        commitPort: memoryTrustActionCommitPort,
      }),
      createEntityIdentityCorrectionActionHandler({
        commitPort: new PostgresEntityIdentityCorrectionCommitPort(),
      }),
    ],
    repository: new PostgresJournalRegenerationActionRepository(
      pool,
      SYNTHETIC_CONTEXT_HMAC_SECRET,
    ),
    entityIdentityCorrectionTargetResolver:
      new PostgresEntityIdentityCorrectionTargetSource(pool),
    trustActionTargetResolver,
  });
  const harness = createConversationAgentHarness({
    actionGateway,
    clock,
    contextCompiler,
    egressPort,
    repository: responseRepository,
  });
  const service = createConversationResponseService({
    actionGateway,
    catalog: MEMORY_TRUST_ACTIONS_CONVERSATION_ACTION_CATALOG,
    clock,
    contextCompiler,
    conversationService,
    harness,
    harnessPolicy: CATALOG_V2_CONVERSATION_HARNESS_POLICY,
    repository: responseRepository,
  });
  const handler = createConversationResponseHandler({
    authenticate: async () => fixedInternalOwnerPrincipal,
    service,
  });
  const retryHandler = createConversationRetryHandler({
    authenticate: async () => fixedInternalOwnerPrincipal,
    service,
  });
  const continuousExchangeService = createContinuousExchangeService({
    clock,
    repository: new PostgresContinuousExchangeRepository(pool),
  });

  // ── run the frozen input through the seam ─────────────────────────────────
  // Every capture starts from a clean memory + conversation slate even when
  // the harness runs more than once over the same schema (the system test
  // does); scenario isolation then truncates between scenarios.
  await pool.query(TWIN_SCENARIO_RESET_TABLES);
  const capturedScenarios: TwinCapturedScenario[] = [];
  for (const [scenarioIndex, scenario] of scenarios.entries()) {
    if (scenarioIndex > 0) {
      await pool.query(TWIN_SCENARIO_RESET_TABLES);
    }
    domainNow = new Date(domainClockStart);
    const scenarioClockStart = domainNow.toISOString();
    log(
      `[twin-${arm}] scenario ${scenario.id} (${scenario.turns.length} turns)`,
    );
    const turns: TwinCapturedTurn[] = [];
    for (const [turnIndex, turn] of scenario.turns.entries()) {
      if (turnIndex > 0) {
        domainNow = new Date(
          domainNow.getTime() + (turn.gapMs ?? DEFAULT_TURN_GAP_MS),
        );
      }
      // Day gaps quiesce the previous Daily Session through the real
      // inactivity machinery before the next turn opens a new one; due
      // consolidation scans queue at the same boundary (memory-on only).
      await continuousExchangeService.scanDueInactivity();
      if (memoryOn) {
        const queued = await memoryConsolidationScan.scanPending();
        const queuedCount =
          queued.daily + queued.weekly + queued.sweeper + queued.reArmed;
        if (queuedCount > 0) {
          log(
            `[twin-${arm}] consolidation scan queued ${queuedCount} command(s) before turn ${turnIndex + 1}`,
          );
        }
        await dispatch();
      }
      const wallStartedAt = performance.now();
      const response = await handler(
        new Request("http://localhost/api/internal/conversation/responses", {
          body: JSON.stringify({
            clientEventId: `${scenario.id}-t${turnIndex + 1}-event`,
            clientTurnId: `${scenario.id}-t${turnIndex + 1}-turn`,
            locale: scenario.locale,
            text: turn.text,
            timezone: scenario.timezone,
          }),
          headers: { "content-type": "application/json" },
          method: "POST",
        }),
      );
      let events = await readNdjson(response);
      // A transient provider failure surfaces as the graceful response_failed
      // event (the production client offers the retry endpoint in exactly
      // this state); the user event is already committed, so replaying the
      // turn through the production retry handler mirrors what a real user
      // does instead of recording a permanently voiceless turn (issue #126
      // evidence runs: one flaked turn at the correction boundary silently
      // broke the whole temporal chain).
      // Bounded to two retry rounds: a real user hits the retry button again
      // when the first retry also fails. The v3.2 full run (2026-08-31) had
      // one turn where both the original response and the single retry
      // failed, leaving a voiceless turn that contaminated the scenario's
      // evidence (temporal-zh t3); a second round minutes later succeeds
      // whenever the failure is a transient provider hiccup. Still bounded —
      // a persistently failing turn must surface as response_failed, never
      // loop.
      for (
        let retryRound = 0;
        retryRound < 2 && events.at(-1)?.type === "response_failed";
        retryRound += 1
      ) {
        const failedTurnId = events.find(
          (event) => event.type === "user_committed",
        )?.turnId;
        if (typeof failedTurnId !== "string") break;
        log(
          `[twin-${arm}] response_failed on turn ${turnIndex + 1}; retry round ${retryRound + 1} via the production retry endpoint`,
        );
        const retryResponse = await retryHandler(
          new Request("http://localhost/api/internal/conversation/responses/retry", {
            body: JSON.stringify({
              originalTurnId: failedTurnId,
              retryRequestId: `${scenario.id}-t${turnIndex + 1}-retry${retryRound + 1}`,
            }),
            headers: { "content-type": "application/json" },
            method: "POST",
          }),
        );
        events = await readNdjson(retryResponse);
      }
      const wallMs = Math.round(performance.now() - wallStartedAt);
      const assistantText = joinDeltas(events);
      const receiptEvent = events.find(
        (event) => event.type === "action_admitted",
      );
      const receipt =
        receiptEvent && isRecord(receiptEvent.receipt)
          ? summarizeReceipt(receiptEvent.receipt)
          : null;
      const evidence = await loadTurnMemoryEvidence(
        pool,
        fixedInternalOwnerPrincipal.userId,
      );
      turns.push({
        assistantText,
        checks: {
          followUpQuestionCount: countFollowUpQuestions(assistantText),
          minimumHighRiskViolations:
            scenario.category === "high_risk" && assistantText.length > 0
              ? [...validateMinimumHighRiskResponse(assistantText).violations]
              : null,
          understandingViolations:
            assistantText.length > 0
              ? [...validateUnderstandingResponse(assistantText).violations]
              : [],
        },
        domainClockIso: domainNow.toISOString(),
        finalEventType: String(events.at(-1)?.type ?? "none"),
        injectedMemories: evidence.injectedMemories,
        input: {
          locale: scenario.locale,
          text: turn.text,
          timezone: scenario.timezone,
        },
        receipt,
        retrieval: evidence.retrieval,
        sequenceInScenario: turnIndex + 1,
        wallMs,
      });
      log(
        `  turn ${turnIndex + 1}: ${String(events.at(-1)?.type ?? "none")} in ${wallMs}ms (${assistantText.length} chars, ${evidence.injectedMemories.length} injected)`,
      );
      if (memoryOn) {
        // The fast-path extraction of this turn's revision (the real outbox
        // machinery; claims become visible per the policy window).
        const outcome = await dispatch();
        if (outcome.failed > 0) {
          log(
            `[twin-${arm}] WARNING: ${outcome.failed} outbox dispatch failure(s) after turn ${turnIndex + 1}`,
          );
        }
      }
    }
    capturedScenarios.push({
      category: scenario.category,
      description: scenario.description,
      domainClockStartIso: scenarioClockStart,
      id: scenario.id,
      languageVariant: scenario.languageVariant,
      turns,
    });
  }

  const contextCompilerSettings = {
    compilerVersion: "context-compiler:v1",
    rawEventTokenBudget: 4_000,
  } as const;
  // The t_auto pin records what the loaded policy actually enforced (the
  // seeded policy row); the constant is the fallback when the run never
  // loaded it (the off arm never dispatches extraction).
  const loadedFastPathPolicy = await fastPathPolicyPromise.catch(() => null);
  const manifest: TwinManifest = {
    artifactClass: "non_authoritative_eval_output",
    arm,
    capturedAt: runStartedAt.toISOString(),
    completedAt: new Date().toISOString(),
    cutoverPins: twinCutoverPins({
      champion,
      registryVersion: predicateRegistrySnapshot.registryVersion,
      tAuto: loadedFastPathPolicy?.tAuto ?? ENTITY_RESOLVE_T_AUTO,
    }),
    dataSourceDeclaration:
      "Fully synthetic scenario material (see the pack file); no real private conversation is read (ADR-0020 Initial Replay, ADR-0071 / ADR-0073 explicit non-authoritative Replay — never production shadowing).",
    databaseIsolation:
      "disposable isolated PostgreSQL schema on the DATABASE_URL server; dropped after the run",
    memoryWriteSwitches: {
      fastPathExtraction: memoryOn,
      memoryConsolidation: memoryOn,
      memoryRetrieval: memoryOn,
    },
    dispatchFailures: dispatchFailureLog,
    roleConfigurations: [
      "memory.extract",
      "entity.resolve",
      "memory.consolidate",
    ].map((role) => {
      const configuration = roleRegistry.configuration(role);
      return {
        configVersion: configuration.configVersion,
        model: configuration.model,
        policyVersion: configuration.policyVersion,
        promptFingerprint: configuration.promptFingerprint,
        role,
      };
    }),
    scenarioIsolation:
      "conversation and memory state (entities, claims, candidates, retrieval runs, trust actions) is reset between scenarios; within-scenario multi-turn and cross-day continuity is preserved",
    scenarioFile,
    seam: "apps/web conversation-response-handler (BFF NDJSON) -> ConversationResponseService -> Conversation Agent Harness + Action Gateway (catalog v2) + Context Compiler (+ Structured-Lexical retrieval in the on arm) -> runtime Provider Egress Port; memory-on also drives the real outbox fast-path extraction and due consolidation scans",
    systemVersions: {
      champion,
      contextCompiler: contextCompilerSettings,
      generationPolicy,
      harnessPolicy: CATALOG_V2_CONVERSATION_HARNESS_POLICY,
      inactivityPolicy,
      providerTransport:
        conversationAdapter.type === "responses-api"
          ? {
              baseUrl: conversationAdapter.baseUrl,
              timeoutMs: conversationAdapter.timeoutMs,
              type: "responses-api",
            }
          : conversationAdapter.type === "opencode-go"
            ? {
                timeoutMs: conversationAdapter.timeoutMs,
                type: "opencode-go",
              }
            : { type: "deterministic" },
    },
  };
  return {
    manifest,
    transcripts: {
      arm,
      capturedAt: runStartedAt.toISOString(),
      scenarios: capturedScenarios,
    },
  };
}
